//! Installable toolchains: the catalog of known releases (URL, size, sha256), embedded in the
//! binary and generated by `cargo xtask catalog` (M3, M4). `CXVM_CATALOG` points at another
//! file with the same format, for tests and mirrors.

use std::path::{Path, PathBuf};

use serde::Deserialize;

use crate::error::{Error, Result};
use crate::files;
use crate::toolchain::{Kind, Spec, ToolchainId};

/// Environment variable naming a catalog file to use instead of the embedded one.
pub const ENV_VAR: &str = "CXVM_CATALOG";

/// The catalog files built into cxvm, one per kind.
const EMBEDDED: [&str; 2] = [
    include_str!("../catalog/clang.toml"),
    include_str!("../catalog/gcc.toml"),
];

/// One installable release.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Release {
    pub id: ToolchainId,
    /// File name of the archive, also its name in the download cache.
    pub asset: String,
    pub url: String,
    /// Archive size in bytes.
    pub size: u64,
    /// Lowercase hex sha256 of the archive.
    pub sha256: String,
    /// Where the checksum comes from, e.g. `attestation` (see docs/backends.md).
    pub source: String,
}

/// The installable releases, sorted by id.
#[derive(Debug, Clone)]
pub struct Catalog {
    releases: Vec<Release>,
    /// The `CXVM_CATALOG` file, or `None` for the embedded catalog.
    origin: Option<PathBuf>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawCatalog {
    #[serde(default)]
    clang: Vec<RawRelease>,
    #[serde(default)]
    gcc: Vec<RawRelease>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawRelease {
    version: String,
    asset: String,
    url: String,
    size: u64,
    sha256: String,
    source: String,
}

const HINT: &str = "fix the file, or unset CXVM_CATALOG to use the catalog built into cxvm";

impl Catalog {
    /// The catalog built into cxvm.
    pub fn embedded() -> Self {
        let mut releases = Vec::new();
        for text in EMBEDDED {
            let catalog = Self::parse(text, None).expect("the embedded catalog is valid");
            releases.extend(catalog.releases);
        }
        releases.sort_by(|a, b| a.id.cmp(&b.id));
        Self {
            releases,
            origin: None,
        }
    }

    /// The catalog in `path` (from `CXVM_CATALOG`), or the embedded one.
    pub fn load(path: Option<&Path>) -> Result<Self> {
        let Some(path) = path else {
            return Ok(Self::embedded());
        };
        let text = std::fs::read_to_string(path).map_err(|source| Error::Io {
            action: "read",
            path: path.to_owned(),
            source,
            hint: "point CXVM_CATALOG at a readable catalog file, or unset it",
        })?;
        Self::parse(&text, Some(path))
    }

    fn parse(text: &str, path: Option<&Path>) -> Result<Self> {
        let invalid = |message: String| Error::InvalidFile {
            path: path.map_or_else(|| "the built-in catalog".into(), Path::to_owned),
            message,
            hint: HINT.into(),
        };
        let raw: RawCatalog =
            toml::from_str(text).map_err(|err| invalid(err.to_string().trim_end().to_owned()))?;
        let entries = (raw.clang.into_iter().map(|entry| (Kind::Clang, entry)))
            .chain(raw.gcc.into_iter().map(|entry| (Kind::Gcc, entry)));
        let mut releases: Vec<Release> = Vec::new();
        for (kind, entry) in entries {
            let id = format!("{kind}@{}", entry.version)
                .parse::<ToolchainId>()
                .ok()
                .filter(|id| id.version().suffix().is_none())
                .ok_or_else(|| invalid(format!("`{}` is not an x.y.z version", entry.version)))?;
            if releases.iter().any(|r| r.id == id) {
                return Err(invalid(format!("{id} is listed twice")));
            }
            if !files::is_plain_file_name(&entry.asset) {
                return Err(invalid(format!(
                    "{id}: asset `{}` is not a plain file name",
                    entry.asset
                )));
            }
            if !(entry.url.starts_with("https://") || entry.url.starts_with("http://")) {
                return Err(invalid(format!("{id}: url `{}` is not http(s)", entry.url)));
            }
            if !is_sha256(&entry.sha256) {
                return Err(invalid(format!(
                    "{id}: sha256 `{}` is not 64 lowercase hex digits",
                    entry.sha256
                )));
            }
            releases.push(Release {
                id,
                asset: entry.asset,
                url: entry.url,
                size: entry.size,
                sha256: entry.sha256,
                source: entry.source,
            });
        }
        releases.sort_by(|a, b| a.id.cmp(&b.id));
        Ok(Self {
            releases,
            origin: path.map(Path::to_owned),
        })
    }

    /// Every release, sorted by kind then version.
    pub fn releases(&self) -> &[Release] {
        &self.releases
    }

    /// Whether any release of `kind` is known.
    pub fn has_kind(&self, kind: Kind) -> bool {
        self.releases.iter().any(|r| r.id.kind() == kind)
    }

    /// The highest release `spec` matches.
    pub fn resolve(&self, spec: &Spec) -> Option<&Release> {
        let id = spec.select(self.releases.iter().map(|r| &r.id))?;
        self.releases.iter().find(|r| &r.id == id)
    }

    /// Where the catalog comes from, for messages.
    pub fn origin(&self) -> String {
        match &self.origin {
            Some(path) => format!("{} (CXVM_CATALOG)", path.display()),
            None => "the catalog built into cxvm".into(),
        }
    }
}

fn is_sha256(hex: &str) -> bool {
    hex.len() == 64 && hex.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'))
}

#[cfg(test)]
mod tests {
    use super::*;

    const SHA: &str = "4a5ec53951a584ed36f80240f6fbf8fdd46b4cf6c7ee87cc2d5018dc37caf679";

    fn entry(version: &str) -> String {
        format!(
            "[[clang]]\nversion = \"{version}\"\nasset = \"LLVM-{version}-Linux-X64.tar.xz\"\n\
             url = \"https://example.invalid/{version}.tar.xz\"\nsize = 10\n\
             sha256 = \"{SHA}\"\nsource = \"attestation\"\n"
        )
    }

    fn parse(text: &str) -> Result<Catalog> {
        Catalog::parse(text, Some(Path::new("/c.toml")))
    }

    #[test]
    fn embedded_catalog_is_valid_and_covers_the_promised_releases() {
        let catalog = Catalog::embedded();
        for id in ["clang@19.1.0", "clang@11.1.0", "gcc@15.2.0", "gcc@8.5.0"] {
            let id: ToolchainId = id.parse().unwrap();
            assert!(catalog.releases().iter().any(|r| r.id == id), "{id}");
        }
        assert!(catalog.releases().iter().all(|r| {
            r.url.starts_with(match r.id.kind() {
                Kind::Clang => "https://github.com/llvm/llvm-project/releases/",
                Kind::Gcc => "https://github.com/xpack-dev-tools/gcc-xpack/releases/",
            })
        }));
        assert!(catalog.releases().is_sorted_by(|a, b| a.id < b.id));
    }

    #[test]
    fn a_catalog_file_may_hold_both_kinds() {
        let gcc = entry("13.3.0").replace("[[clang]]", "[[gcc]]");
        let catalog = parse(&[entry("19.1.0"), gcc, entry("13.3.0")].join("\n")).unwrap();
        let ids: Vec<String> = catalog
            .releases()
            .iter()
            .map(|r| r.id.to_string())
            .collect();
        assert_eq!(ids, ["gcc@13.3.0", "clang@13.3.0", "clang@19.1.0"]);
        assert!(catalog.has_kind(Kind::Gcc));
        let resolved = catalog.resolve(&"gcc@13".parse().unwrap()).unwrap();
        assert_eq!(resolved.id.to_string(), "gcc@13.3.0");
    }

    #[test]
    fn resolves_partial_versions_to_the_highest_release() {
        let catalog =
            parse(&[entry("18.1.8"), entry("19.1.7"), entry("19.1.0")].join("\n")).unwrap();
        let resolve = |s: &str| {
            catalog
                .resolve(&s.parse().unwrap())
                .map(|r| r.id.to_string())
        };
        assert_eq!(resolve("clang@19").as_deref(), Some("clang@19.1.7"));
        assert_eq!(resolve("clang@18.1.8").as_deref(), Some("clang@18.1.8"));
        assert_eq!(resolve("clang@20"), None);
        assert_eq!(resolve("gcc@19"), None);
        assert_eq!(resolve("clang@19-local"), None);
        assert_eq!(resolve("system"), None);
        let ids: Vec<String> = catalog
            .releases()
            .iter()
            .map(|r| r.id.to_string())
            .collect();
        assert_eq!(ids, ["clang@18.1.8", "clang@19.1.0", "clang@19.1.7"]);
    }

    #[test]
    fn rejects_invalid_entries_naming_the_file() {
        for (text, reason) in [
            (entry("19.1"), "not an x.y.z"),
            (entry("19.1.0-local"), "not an x.y.z"),
            ([entry("19.1.0"), entry("19.1.0")].join("\n"), "twice"),
            (
                entry("19.1.0").replace("LLVM-19", "../LLVM-19"),
                "plain file name",
            ),
            (entry("19.1.0").replace("https://", "file://"), "not http"),
            (
                entry("19.1.0").replace(SHA, &SHA.to_uppercase()),
                "64 lowercase hex",
            ),
            (
                entry("19.1.0").replace("size = 10", "size = 10\nextra = 1"),
                "unknown field",
            ),
            ("[[rust]]\n".into(), "unknown field"),
        ] {
            let err = parse(&text).unwrap_err().to_string();
            assert!(err.contains("/c.toml"), "{err}");
            assert!(err.contains(reason), "expected {reason:?} in {err}");
            assert!(err.contains("CXVM_CATALOG"), "{err}");
        }
    }

    #[test]
    fn loads_a_catalog_file() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("c.toml");
        std::fs::write(&path, entry("19.1.0")).unwrap();
        let catalog = Catalog::load(Some(&path)).unwrap();
        assert_eq!(catalog.releases().len(), 1);
        assert!(catalog.origin().contains("CXVM_CATALOG"));
        let err = Catalog::load(Some(&dir.path().join("missing.toml"))).unwrap_err();
        assert!(err.to_string().contains("CXVM_CATALOG"), "{err}");
    }
}
